	    // Two-dimensional case
	    result.append("\n(");
	    result.append(dim_x);
	    result.append(",");
	    result.append(dim_y);
	    result.append(")\n[");
	    for (int i = 0; i < dim_x; i++) {
		for (int j = 0; j < dim_y; j++) {
