// kernel (a) over an array of the runtime's boxes: Box[] storage, one fresh
// box per multiply and per add, as CompilerBuiltin's arithmetic does.
// 4192-element dot product, 200 reps; 4192 is exactly nParams() of
// MicroGptFlat, the flat parameter vector Adam touches.
// work() is one Fortress run of the timed loop (200 reps).  One untimed
// warm-up pass, then MULT timed passes; loop_ns is their mean, so it is
// directly comparable with the Fortress loop_ns.
public class KDotBoxed {
    static final int N = 4192, REPS = 200;
    static double work() {
        Box[] x = new Box[N], y = new Box[N];
        for (int i = 0; i < N; i++) { x[i] = Box.make((i % 17 + 1) / 17.0); y[i] = Box.make((i % 23 + 1) / 23.0); }
        Box s = Box.make(0.0);
        for (int r = 0; r < REPS; r++) {
            Box d = Box.make(0.0);
            for (int i = 0; i < N; i++) d = Box.add(d, Box.mul(x[i], y[i]));
            s = Box.add(s, d); }
        return s.getValue(); }

    public static void main(String[] args) {
        int mult = args.length > 0 ? Integer.parseInt(args[0]) : 20;
        double s = work();
        long t0 = System.nanoTime();
        for (int m = 0; m < mult; m++) s = work();
        long t1 = System.nanoTime();
        System.out.println("kdot " + s);
        System.out.println("loop_ns " + ((t1 - t0) / mult));
    }
}

// The runtime's box, in the shape the generated code uses it: modelled on
// com.sun.fortress.compiler.runtimeValues.FRR64 -- final class, final double
// field, private constructor, static make(), no cache -- and on the generated
// native wrapper for simpleDoubleArith, which does
//     getValue(); getValue(); <primitive op>; FRR64.make(...)
// Shared by every boxed form in this directory.
public final class Box {
    final double val;
    private Box(double x) { val = x; }
    public double getValue() { return val; }
    public static Box make(double x) { return new Box(x); }
    public static Box mul(Box a, Box b) { return make(a.getValue() * b.getValue()); }
    public static Box add(Box a, Box b) { return make(a.getValue() + b.getValue()); }
    public static Box sub(Box a, Box b) { return make(a.getValue() - b.getValue()); }
    public static Box div(Box a, Box b) { return make(a.getValue() / b.getValue()); }
    public static Box sqrt(Box a) { return make(Math.sqrt(a.getValue())); }
}
